cypress_script:
describe('Image Accessibility and Integrity', () => {
  it('should display the Broken Images heading and footer', () => {
    cy.visit('https://the-internet.herokuapp.com/broken_images');
    cy.get('h1').should('have.text', 'Broken Images');
    cy.get('#page-footer').should('be.visible');
  });
  it('should not display broken images', () => {
    cy.visit('https://the-internet.herokuapp.com/broken_images');
    cy.get('#content').should('be.visible');
  });
});

playwright_script:
import { test, expect } from '@playwright/test';

 test.describe('Image Accessibility and Integrity', () => {
   test('should display the Broken Images heading and footer', async ({ page }) => {
     await page.goto('https://the-internet.herokuapp.com/broken_images');
     const heading = await page.locator('h1');
     await expect(heading).toHaveText('Broken Images');
     const footer = await page.locator('#page-footer');
     await expect(footer).toBeVisible();
   });
   test('should not display broken images', async ({ page }) => {
     await page.goto('https://the-internet.herokuapp.com/broken_images');
     const content = await page.locator('#content');
     await expect(content).toBeVisible();
   });
 });
